// Des: Scheduler core: Sche struct; method parts in tk-tick-*.zig
// Flo: own thread 1s tick (accept loop would only tick on page loads) > reload on mtime > collect due under mutex (guards load+arme only, never held while a task runs) > queue > worker pool (same lock never overlaps) > retry requeue > log + link/chain next tick | probes sense on their own thread (blocking connect)
// I/O: aa-auto-task.json (stor) > Sche state read by routes (counters, last runs, queue, chains), task logs in data folder/task-log, NDJSON discarded
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const time = @import("tasktime"); const armz = @import("taskarm"); const spaw = @import("spawn"); const regi = @import("registry"); const supe = @import("tasksuper"); const prob = @import("taskprobe"); const conf = @import("store"); const stre = @import("stream");
const base = @import("tk-tick-base.zig"); const chaipart = @import("tk-tick-chai.zig"); const looppart = @import("tk-tick-loop.zig"); const manupart = @import("tk-tick-manu.zig"); const workpart = @import("tk-tick-work.zig"); const logzpart = @import("tk-tick-logz.zig");
pub const CF = base.CF; pub const ArmeReje = base.ArmeReje;
pub const Sche = struct {
gpaz: std.mem.Allocator = undefined, root: []const u8 = "", mute: std.Io.Mutex = .init, load: ?stor.Load = null, arme: []armz.Armed = &.{}, arme_erro: []ArmeReje = &.{},
tick_coun: std.atomic.Value(u32) = .init(0), relo_coun: std.atomic.Value(u32) = .init(0), fire_coun: std.atomic.Value(u32) = .init(0), star_msec: i64 = 0, sola: ?armz.SolarConfig = null, last_minu: i64 = -1,
logz_warn: std.atomic.Value(bool) = .init(false), runz_warn: std.atomic.Value(bool) = .init(false), done: supe.DoneRing = .{}, loop: std.StringHashMapUnmanaged(*supe.Supe) = .empty,
chai: [CF.chai_maxz]ChaiRunz = @splat(.{}), abor_buff: [128]u8 = undefined, abor_leng: usize = 0, boot: std.StringHashMapUnmanaged(void) = .empty, prng: ?std.Random.DefaultPrng = null, chai_pers: bool = false, chai_ring: bool = false,
manu: [CF.manu_maxz]?*regi.Ring = @splat(null), regz: regi.Regi = .{}, iozz_dein: ?std.Io = null, read: std.atomic.Value(bool) = .init(false),
queu_mute: std.Io.Mutex = .init, queu: std.ArrayList(*Jobz) = .empty, queu_work: u32 = 0, runn: [CF.work_maxz]RunzSlot = @splat(.{}), toas: std.atomic.Value(u32) = .init(0),
last_runz_mute: std.Io.Mutex = .init, last_runz_cach: std.StringHashMapUnmanaged(RunzLastReco) = .empty,
stop: std.atomic.Value(bool) = .init(false), exit: std.atomic.Value(bool) = .init(false), prob_exit: std.atomic.Value(bool) = .init(false),
pub const CatcReqz = base.CatcReqz; pub const ChaiFini = base.ChaiFini; pub const ChaiRunz = base.ChaiRunz; pub const PausCode = regi.PausCode; pub const ChaiView = base.ChaiView; pub const Jobz = base.Jobz; pub const PollReqz = base.PollReqz; pub const RunzLast = base.RunzLast; pub const RunzLastReco = base.RunzLastReco; pub const RunzResu = base.RunzResu; pub const RunzSlot = base.RunzSlot; pub const StarReqz = base.StarReqz; pub const chaiResu = base.chaiResu; pub const finiPush = base.finiPush; pub const intoDupe = base.intoDupe; pub const jobzClon = base.jobzClon; pub const jobzFill = base.jobzFill; pub const logzDirz = base.logzDirz; pub const logzRota = base.logzRota; pub const membNext = base.membNext; pub const nowzMsec = base.nowzMsec; pub const plusPick = base.plusPick; pub const poolCoun = base.poolCoun; pub const poolPick = base.poolPick; pub const recoLast = base.recoLast; pub const ringDrop = base.ringDrop; pub const ringNote = base.ringNote; pub const ringSeal = base.ringSeal; pub const taskFind = base.taskFind; 
pub const stepRingNewz = chaipart.stepRingNewz; pub const chaiSlot = chaipart.chaiSlot; pub const plusDraw = chaipart.plusDraw; pub const chaiSave = chaipart.chaiSave; pub const chaiForg = chaipart.chaiForg; pub const virtFill = chaipart.virtFill; pub const chaiTick = chaipart.chaiTick; pub const chaiLogz = chaipart.chaiLogz; pub const chaiView = chaipart.chaiView; pub const chaiAbor = chaipart.chaiAbor; pub const chaiPaus = chaipart.chaiPaus; pub const chaiRing = chaipart.chaiRing; pub const chaiJobzWrit = chaipart.chaiJobzWrit; pub const aborTake = chaipart.aborTake; 
pub const loopReco = looppart.loopReco; pub const loopStar = looppart.loopStar; pub const loopStop = looppart.loopStop; pub const loopEmerStop = looppart.loopEmerStop; pub const loopAllzStop = looppart.loopAllzStop; pub const loopThre = looppart.loopThre; pub const probThre = looppart.probThre; pub const probPoll = looppart.probPoll; pub const loopStat = looppart.loopStat; pub const probStat = looppart.probStat; 
pub const ManuCode = manupart.ManuCode; pub const ManuRes = manupart.ManuRes; pub const manuRun = manupart.manuRun; pub const manuRing = manupart.manuRing; pub const manuAbor = manupart.manuAbor; pub const manuJobzWrit = manupart.manuJobzWrit;
pub const jobzFree = workpart.jobzFree; pub const disp = workpart.disp; pub const queuEnqu = workpart.queuEnqu; pub const queuRequ = workpart.queuRequ; pub const workWake = workpart.workWake; pub const runnLockIszz = workpart.runnLockIszz; pub const lockHeldIszz = workpart.lockHeldIszz; pub const lockPick = workpart.lockPick; pub const workMain = workpart.workMain; pub const queuWrit = workpart.queuWrit; pub const jobzExec = workpart.jobzExec; pub const jobzRunz = workpart.jobzRunz; pub const fireLogz = workpart.fireLogz; pub const failNoti = workpart.failNoti; pub const toasThre = workpart.toasThre; pub const workBusy = workpart.workBusy; 
pub const logzRead = logzpart.logzRead; pub const runzLast = logzpart.runzLast; pub const cachPutz = logzpart.cachPutz; pub const runzNote = logzpart.runzNote; pub const runzLastPrim = logzpart.runzLastPrim; pub const primMain = logzpart.primMain; pub const catcScan = logzpart.catcScan; pub const runzLastLogz = logzpart.runzLastLogz; pub const fireCoun = logzpart.fireCoun; pub const fireNext = logzpart.fireNext; 
pub fn star(self: *Sche, gpaz: std.mem.Allocator, iozz: std.Io, root: []const u8) !void { self.gpaz = gpaz; self.root = try gpaz.dupe(u8, root); self.star_msec = nowzMsec(iozz); self.regz.gpaz = gpaz; self.iozz_dein = iozz; self.relo(iozz) catch {}; self.loopReco(iozz); self.runzLastPrim(iozz); self.catcScan(iozz); self.chai_pers = true; self.chai_ring = true; self.read.store(true, .release); const thre = try std.Thread.spawn(.{}, threMain, .{ self, iozz }); thre.detach(); const prbt = try std.Thread.spawn(.{}, probThre, .{ self, iozz }); prbt.detach(); }
pub fn dein(self: *Sche) void { self.stop.store(true, .release); if (self.iozz_dein) |iozz| { var wait: u32 = 0; while (wait < CF.stop_wait_msec) { if (self.exit.load(.acquire) and self.prob_exit.load(.acquire) and !self.workBusy(iozz)) break; std.Io.sleep(iozz, .fromMilliseconds(CF.stop_slic_msec), .awake) catch break; wait += CF.stop_slic_msec; } } if (self.iozz_dein) |iozz| self.loopAllzStop(iozz); self.regz.dein(self.gpaz); var iter = self.boot.keyIterator(); while (iter.next()) |keyz| self.gpaz.free(keyz.*); self.boot.deinit(self.gpaz); self.boot = .empty; for (self.queu.items) |pntr| self.jobzFree(pntr); for (&self.chai) |*chai| ringDrop(chai); for (&self.manu) |*slot| { if (slot.*) |ring| ring.rele(); slot.* = null; } self.queu.deinit(self.gpaz); self.queu = .empty; var lite = self.last_runz_cach.keyIterator(); while (lite.next()) |keyz| self.gpaz.free(keyz.*); self.last_runz_cach.deinit(self.gpaz); self.last_runz_cach = .empty; self.armeClea(); if (self.load) |*load| load.dein(); self.load = null; if (self.root.len > 0) self.gpaz.free(self.root); self.root = ""; }
fn armeClea(self: *Sche) void { if (self.arme.len > 0) self.gpaz.free(self.arme); self.arme = &.{}; if (self.arme_erro.len > 0) self.gpaz.free(self.arme_erro); self.arme_erro = &.{}; }
pub fn relo(self: *Sche, iozz: std.Io) !void { const fresh = try stor.load(self.gpaz, iozz, self.root); var arme_list: std.ArrayList(armz.Armed) = .empty; var erro_list: std.ArrayList(ArmeReje) = .empty; errdefer arme_list.deinit(self.gpaz); errdefer erro_list.deinit(self.gpaz); for (fresh.task) |task| { if (!task.on) continue; if (stor.chaiFind(fresh.task, task.id) != null) continue; var arme = armz.armTask(task) catch |erro| { erro_list.append(self.gpaz, .{ .iden = task.id, .whyz = @errorName(erro) }) catch {}; continue; }; if (std.mem.eql(u8, task.type, "once")) { var temp = std.heap.ArenaAllocator.init(self.gpaz); defer temp.deinit(); const allo = temp.allocator(); const stam = stor.onceStamRead(allo, iozz, task.id); if (stam.len > 0) { if (std.mem.eql(u8, stam, task.sche orelse "")) { arme.fired = true; } else { stor.onceFireClea(allo, iozz, task.id); } } } arme_list.append(self.gpaz, arme) catch {}; } const arme_empt: []armz.Armed = &[_]armz.Armed{}; const erro_empt: []ArmeReje = &[_]ArmeReje{}; const arme_newz = arme_list.toOwnedSlice(self.gpaz) catch arme_empt; const erro_newz = erro_list.toOwnedSlice(self.gpaz) catch erro_empt; try self.mute.lock(iozz); const oldz = self.load; const arme_oldz = self.arme; const erro_oldz = self.arme_erro; self.load = fresh; self.arme = arme_newz; self.arme_erro = erro_newz; self.last_minu = -1; self.runzStatCarr(iozz); self.mute.unlock(iozz); if (arme_oldz.len > 0) self.gpaz.free(arme_oldz); if (erro_oldz.len > 0) self.gpaz.free(erro_oldz); if (oldz) |valu| { var mutz = valu; mutz.dein(); } _ = self.relo_coun.fetchAdd(1, .monotonic); }
pub const Snap = struct { tota: usize, arme: usize, offz: usize, reje: usize, rawz_okay: bool, tick_coun: u32, relo_coun: u32, fire_coun: u32, arme_erro: usize, upti_msec: i64, read: bool };
pub fn snap(self: *Sche, iozz: std.Io) Snap { var resu: Snap = .{ .tota = 0, .arme = 0, .offz = 0, .reje = 0, .rawz_okay = false, .tick_coun = self.tick_coun.load(.monotonic), .relo_coun = self.relo_coun.load(.monotonic), .fire_coun = self.fire_coun.load(.monotonic), .arme_erro = 0, .upti_msec = nowzMsec(iozz) - self.star_msec, .read = self.read.load(.acquire) }; self.mute.lock(iozz) catch return resu; defer self.mute.unlock(iozz); resu.arme_erro = self.arme_erro.len; if (self.load) |load| { resu.tota = load.task.len; resu.reje = load.reje.len; resu.rawz_okay = load.rawz_okay; for (load.task) |task| { if (task.on) resu.arme += 1 else resu.offz += 1; } } return resu; }
pub fn tick(self: *Sche, iozz: std.Io) void { _ = self.tick_coun.fetchAdd(1, .monotonic); const nowz = time.localNow(); const nowz_msec = nowzMsec(iozz); var duez_buff: [64]Jobz = undefined; var duez_coun: usize = 0; var pend: supe.DoneRing = .{}; var fini_buff: [CF.chai_fini_maxz]ChaiFini = undefined; var fini_coun: usize = 0; { self.mute.lock(iozz) catch return; defer self.mute.unlock(iozz); const list = if (self.load) |load| load.task else &[_]stor.Task{}; pend = self.done; self.done.clea(); for (pend.item()) |*done| { for (self.arme) |*arme| { if (duez_coun >= duez_buff.len) break; const spec = arme.linkSpec() orelse continue; if (!supe.linkMatc(spec, done)) continue; const task = taskFind(list, arme.id) orelse continue; const jobz = &duez_buff[duez_coun]; jobzFill(jobz, arme.id, task); jobz.dept = done.dept + 1; arme.markFired(nowz_msec); duez_coun += 1; } } self.chaiTick(iozz, nowz, nowz_msec, pend.item(), list, &duez_buff, &duez_coun, &fini_buff, &fini_coun); for (self.arme) |*arme| { if (duez_coun >= duez_buff.len) break; if (arme.isChain()) continue; if (!arme.due(iozz, nowz, nowz_msec, self.sola)) continue; if (arme.isBoot()) self.bootNote(arme.id); const task = taskFind(list, arme.id) orelse continue; const jobz = &duez_buff[duez_coun]; jobzFill(jobz, arme.id, task); jobz.queu_file = intoDupe(&jobz.queu_file_buff, arme.claimedFile()); jobz.queu_dirz = intoDupe(&jobz.queu_dirz_buff, if (jobz.queu_file.len > 0) (task.sche orelse "") else ""); if (std.mem.eql(u8, task.type, "once")) { jobz.once_stam = intoDupe(&jobz.once_buff, task.sche orelse ""); } arme.markFired(nowz_msec); duez_coun += 1; } } if (duez_coun > 0) { _ = self.fire_coun.fetchAdd(@intCast(duez_coun), .monotonic); self.disp(iozz, duez_buff[0..duez_coun]); } for (fini_buff[0..fini_coun]) |*fini| self.chaiLogz(iozz, fini); }
pub fn bootNote(self: *Sche, iden: []const u8) void { if (self.boot.contains(iden)) return; const keyz = self.gpaz.dupe(u8, iden) catch return; self.boot.put(self.gpaz, keyz, {}) catch self.gpaz.free(keyz); }
pub fn runzStatCarr(self: *Sche, iozz: std.Io) void { for (self.arme) |*arme| { if (arme.isBoot() and self.boot.contains(arme.id)) arme.markBootFired(); } var gone: [32][]const u8 = undefined; var gone_coun: usize = 0; var iter = self.boot.keyIterator(); while (iter.next()) |keyz| { const live = for (self.arme) |*arme| { if (arme.isBoot() and std.mem.eql(u8, arme.id, keyz.*)) break true; } else false; if (!live and gone_coun < gone.len) { gone[gone_coun] = keyz.*; gone_coun += 1; } } for (gone[0..gone_coun]) |keyz| { if (self.boot.fetchRemove(keyz)) |pair| self.gpaz.free(pair.key); } for (&self.chai) |*chai| { if (!chai.used) continue; const live = for (self.arme) |*arme| { if (arme.isChain() and std.mem.eql(u8, arme.id, chai.name())) break true; } else false; if (live) continue; self.chaiForg(iozz, chai); chai.* = .{}; } if (self.chai_pers) if (self.load) |load| for (load.task) |task| { if (stor.chaiChec(task) and !task.on) { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); stor.chaiStatClea(aren.allocator(), iozz, task.id); } }; }
fn threMain(self: *Sche, iozz: std.Io) void { defer self.exit.store(true, .release); var last_mtim: i128 = stor.mtimMsec(iozz, self.root); var poll_msec: u32 = 0; var last_real = nowzMsec(iozz); var last_awak = std.Io.Clock.awake.now(iozz).toMilliseconds(); while (!self.stop.load(.acquire)) { const real = nowzMsec(iozz); const awak = std.Io.Clock.awake.now(iozz).toMilliseconds(); if ((real - last_real) - (awak - last_awak) > CF.wake_gapz_msec) self.catcScan(iozz); last_real = real; last_awak = awak; self.tick(iozz); poll_msec += CF.tick_msec; if (poll_msec >= CF.relo_poll_msec) { poll_msec = 0; const mtim = stor.mtimMsec(iozz, self.root); if (mtim != 0 and mtim != last_mtim) { last_mtim = mtim; self.relo(iozz) catch {}; self.loopReco(iozz); } } std.Io.sleep(iozz, .fromMilliseconds(CF.tick_msec), .awake) catch break; } }
};
